solutionCode:
function App() {
  const [rating, setRating] = useState(0);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      {[1, 2, 3, 4, 5].map(n => (
        <button key={n} aria-label={n + ' stars'} onClick={() => setRating(n)}
          style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: 28, color: '#f59e0b' }}>
          {n <= rating ? '★' : '☆'}
        </button>
      ))}
    </div>
  );
}

