solutionCode:
function App() {
  const [q, setQ] = useState('');
  const names = ['Anna', 'Bob', 'Anand', 'Carl'];
  const shown = names.filter(n => n.toLowerCase().includes(q.toLowerCase()));
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={q} onChange={e => setQ(e.target.value)} placeholder="Search names" />
      <ul>{shown.map(n => <li key={n}>{n}</li>)}</ul>
    </div>
  );
}

