solutionCode:
function App() {
  const items = [{ q: 'Q1', a: 'Answer one' }, { q: 'Q2', a: 'Answer two' }];
  const [open, setOpen] = useState(null);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      {items.map((it, i) => (
        <div key={i}>
          <button onClick={() => setOpen(open === i ? null : i)}>{it.q}</button>
          {open === i && <div>{it.a}</div>}
        </div>
      ))}
    </div>
  );
}
